head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70012";
scwin.divAlertMsg = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.kclicUsrTpId

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "docpathframe", attr: "src", fn: function () { return "/submission/disclosure.do?method=searchFormIframe&formCd=" + String(dma_formMap.get("formCd")); } },
        { childId: "waring_cell", attr: "__html", fn: function () { return ([String(String((dma_pageContext.get("formWrtCautnContn") ?? "")))].some(function (v) { return String(v == null ? '' : v).trim() !== ''; }) ? ("<strong style=\"display:block; margin-bottom:7px; padding-left:20px; height:20px; line-height:20px; font-size:14px; font-weight:bold; color:#fe7203; background:url(../img/ic_tip.png) no-repeat 0 2px;\">기재상 주의사항</strong> " + String(String((dma_pageContext.get("formWrtCautnContn") ?? "")))) : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "btn_alertE", fn: function(){ return (String($c.session.getUserInfo("kclicUsrTpId")).indexOf('CHRG_INST_KRX_') !== -1 ||  $c.session.getUserInfo("kclicUsrTpId") === 'CHRG_INST_ETC'); } }, { id: "c_otherwise_42", fn: function(){ return (!((String($c.session.getUserInfo("kclicUsrTpId")).indexOf('CHRG_INST_KRX_') !== -1 ||  $c.session.getUserInfo("kclicUsrTpId") === 'CHRG_INST_ETC'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb1", fn: function () { return "제출처: " + String(dma_formMap.get("formAdmTnstTpNm")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $('#waringCheck label').click(function() {
                if (!$(this).hasClass('on')) {
                    $(this).addClass('on');
                    $('#txt_waring').fadeIn('fast');
                    $('html, body').animate({ scrollTop: $('#txt_waring').offset().top - ($('#headerArea').height() + 10) }, 500);
                } else {
                    $(this).removeClass('on');
                    $('#txt_waring').fadeOut('fast');
                }
        });
        scwin.sectionH();
        $(window).resize(function() {
                scwin.sectionH();
        });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70012.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.divAlertMsg = $c.util.getComponent('divAlertMsg');
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70012.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_window_onclick
 * @description 「레이어닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70012.btn_window_onclick' }); }
};

/**
 * @method
 * @name btn_openPopupExample_onclick
 * @description 「샘플보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_openPopupExample_onclick = function(e){
    try {
        scwin.openPopupExample('' + dma_formMap.get("formCd") + '')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70012.btn_openPopupExample_onclick' }); }
};

/**
 * @method
 * @name btn_alertE_onclick
 * @description 「공시작성」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_alertE_onclick = async function(e){
    try {
        await alertE('화면 접근권한이 제한되어 있습니다. \n상장법인 담당자만 접근 가능합니다.')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70012.btn_alertE_onclick' }); }
};

/**
 * @method
 * @name btn_createForm_onclick
 * @description 「공시작성」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_createForm_onclick = async function(e){
    try {
        await scwin.createForm('' + dma_formMap.get("formAdmTnstTpCd") + '','' + dma_formMap.get("formCd") + '','' + dma_formMap.get("foreVersion") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70012.btn_createForm_onclick' }); }
};

/**
 * @method
 * @name btn_print_onclick
 * @description 「인쇄」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_print_onclick = function(e){
    try {
        scwin.print()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70012.btn_print_onclick' }); }
};

/**
 * @method
 * @name btn_docDownLoad_onclick
 * @description 「저장」 클릭 이벤트
