/**
 * @method
 * @name a_57_onclick
 * @description a_57 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.a_57_onclick = function(e){
    try {

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70012.a_57_onclick' }); }
};

/**
 * @method
 * @name btn_closeAlertE_onclick
 * @description 「확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
