///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_docDownLoad
 * @description doc Down Load 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_docDownLoad = async function () {
    try { return await $c.data.downFile("/submission/disclosure.do?method=searchFormDownLoad", "", ($c.util.getComponent("dma_docDownLoadReq") ? $c.util.getComponent("dma_docDownLoadReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_excelDownLoad
 * @description excel Down Load 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_excelDownLoad = async function () {
    try { return await $c.data.downFile("/submission/disclosure.do?method=searchExcelDownLoad", "", ($c.util.getComponent("dma_excelDownLoadReq") ? $c.util.getComponent("dma_excelDownLoadReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name sectionH
 * @description section H 처리
 * @returns {void}
 * @hidden N
 */
scwin.sectionH = function () {
    $('#sectionArea').css({ 'paddingTop': $('#headerArea').height() });
};

/**
 * @method
 * @name scrollLink
 * @description scroll Link 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.scrollLink = function (obj) {
    const pos = $("#" + obj).offset();
    $("html,body").animate({ scrollTop: pos.top - 75 }, 500);
};

/**
 * @method
 * @name docDownLoad
 * @description doc Down Load 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.docDownLoad = async function () {
    const waringchVal = $('#waringCheck label').hasClass('on') === true ? "1" : "0";
    $c.util.getComponent('ipt_waringchVal').setValue(waringchVal);
    await scwin.tx_docDownLoad();
};

/**
 * @method
 * @name fnOpenPopup
 * @description fn Open Popup 처리
 * @param {*} pageURL pageURL
 * @returns {void}
 * @hidden N
 */
scwin.fnOpenPopup = function (pageURL) {
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(pageURL), { id: "remoteWin", scrollbars: true, resizable: false, width: "835", height: "695", type: "pageFramePopup" }, {});
};

/**
 * @method
 * @name openPopupExample
 * @description open Popup Example 처리
 * @param {String} formCd formCd
 * @returns {void}
 * @hidden N
 */
scwin.openPopupExample = function (formCd) {
    scwin.fnOpenPopup('/discls/sample.do?method=exampleList&formCd=' + formCd);
};

/**
 * @method
 * @name print
 * @description print 처리
 * @returns {void}
 * @hidden N
 */
scwin.print = function () {
    const formAdmTnstTpCd = '' + dma_formMap.get("formAdmTnstTpCd") + '';
    document.print_iframe.setStyle("display", "");
    let bodyHtml = $("#docpathframe").contents().find("body").html();
    if (formAdmTnstTpCd !== '1') {
        bodyHtml = '<table><tr><td>' + bodyHtml + '</td></tr></table>';
    }
    if ($('#waringCheck label').hasClass('on')) {
        $("#print_iframe").contents().find("head").html($("#docpathframe").contents().find("head").html() + $("#print_iframe").contents().find("head").html());
        $("#print_iframe").contents().find("#formArea").html(bodyHtml);
        $("#print_iframe").contents().find("#waring").html($c.util.getComponent('txt_waring').getValue());
        $("#print_iframe").contents().find("#waring").attr("style", "margin-top:20px; padding:12px; font-size:13px; text-align:left; border:2px solid #e1e1e1; background:#f4f4f4;");
    } else {
        $("#print_iframe").contents().find("head").html($("#docpathframe").contents().find("head").html() + $("#print_iframe").contents().find("head").html());
        $("#print_iframe").contents().find("#formArea").html(bodyHtml);
        $("#print_iframe").contents().find("#waring").attr("style", "");
        /* TODO Stage2: [sdd] 미실현 동작: set_label (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_label — {target}.setLabel({args}) */
    }
    document.print_iframe.focus();
    /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
    frames['print_iframe'].print();
    document.print_iframe.setStyle("display", "none");
};

/**
 * @method
 * @name createForm
 * @description create Form 처리
 * @param {String} formAdmInstTpCd formAdmInstTpCd
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.createForm = async function (formAdmInstTpCd, formCd, formVer) {
    if (formAdmInstTpCd === '2') {
        let url = "/submission/disclosure.do?method=createDartFormPreview&formCd=" + formCd;
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        $c.win.setPageFrameSrc(null, (function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url));
    } else {
        await alertE('해당서식은 기본정보의 기타메뉴에서 조회공시 요구 및 답변 내역의 답변버튼을 클릭하여 작성하셔야 합니다.');
        return;
        url = "/submission/disclosure.do?method=createForm&formCd=" + formCd;
        // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
        $c.win.setPageFrameSrc(null, (function (__u) { __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url));
    }
    $c.win.closePopup();
};

/**
 * @method
 * @name autoResize
 * @description auto Resize 처리
 * @param {*} id id
 * @returns {void}
 * @hidden N
 */
scwin.autoResize = function (id) {
    let he;
    let wi;
    if (document.getElementById) {
        he = $c.util.getComponent(id).contentWindow.document.body.scrollHeight;
        wi = $c.util.getComponent(id).contentWindow.document.body.scrollWidth;
    }
    wi = wi + 25;
    $c.util.getComponent(id).height = (he) + 'px';
    $c.util.getComponent(id).width = (wi) + 'px';
    scwin.sectionH();
};

/**
 * @method
 * @name alertE
 * @description alert E 처리
 * @param {String} msg 항목명
 * @param {*} callback callback
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

/**
 * @method
 * @name closeAlertE
 * @description close Alert E 처리
 * @returns {void}
 * @hidden N
 */
scwin.closeAlertE = function () {
    scwin.divAlertMsg.setStyle("display", "none");
    if (g_callback != null && (g_callback || g_callback !== "")) {
        g_callback();
    }
};

/**
 * @method
 * @name excelDownLoad
 * @description excel Down Load 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDownLoad = async function () {
    const waringchVal = $('#waringCheck label').hasClass('on') === true ? "1" : "0";
    $c.util.getComponent('ipt_excelWaringchVal').setValue(waringchVal);
    await scwin.tx_excelDownLoad();
};
